# Generated by build.py from recipe.yml for recipe http-replay-a-request-from-a-trace. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'reports' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.csv'), "id,total`n1,42`n")
[IO.File]::WriteAllText((Join-Path $PWD 'reports/report.csv'), "id,total`n1,42`n")
[IO.File]::WriteAllText((Join-Path $PWD 'request-of.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Writes to standard output the bytes one exchange received, as surl's --trace dumped them:`n# the hex columns of that exchange's `"<= Recv data`" blocks, turned back into bytes.`n# WHICH is the exchange's number, or text from one of surl's own lines about it, such as`n# MalformedHeaderField; then the last exchange with such a line is the one taken.`n# Run: sh request-of.sh trace.txt WHICH > request.http   (needs a POSIX shell: Git Bash on Windows)`ntrace=`$1`nwhich=`$2`ncase `$which in`n  '' | *[!0-9]*) n=`$(grep '^#[0-9]* \* ' `"`$trace`" | grep -F -- `"`$which`" | tail -n 1 | cut -d' ' -f1 | tr -d '#') ;;`n  *) n=`$which ;;`nesac`nif [ -z `"`$n`" ]; then echo `"no exchange in `$trace has a line with `$which`" >&2; exit 1; fi`n`n# A data line is an offset, then up to 16 bytes as two hex digits each, then the same bytes as text.`nLC_ALL=C awk -v n=`"#`$n`" '`n  function hex(h) { return (index(`"0123456789abcdef`", substr(h, 1, 1)) - 1) * 16 + index(`"0123456789abcdef`", substr(h, 2, 1)) - 1 }`n  `$1 == n { received = (`$2 == `"<=`"); next }`n  /^#/ { received = 0; next }`n  received { for (i = 2; i <= 17 && `$i ~ /^[0-9a-f][0-9a-f]`$/; i++) printf `"%c`", hex(`$i) }`n' `"`$trace`"`n")
$server0 = Start-Process surl -ArgumentList '--trace', 'trace.txt', '--idle-timeout', '2', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh request-of.sh trace.txt MalformedHeaderField > request.http && curl -s -m 10 -T request.http telnet://127.0.0.1:8080 } finally { Stop-Process $server0 }
